 grid=np.linspace(R,0,P['caps']['design_nodes']);solution=solve_ivp(equation,(R,0),[0.],method='DOP853',rtol=P['tolerances']['ODE_rtol'],atol=P['tolerances']['ODE_atol'],max_step=R*P['tolerances']['maximum_step_over_radius'],t_eval=grid);save('solver.json',dict(success=bool(solution.success),message=solution.message,nfev=solution.nfev,initialization='One-sided crease limit B(R)=0; not an actual transmitted tangent ray.'));assert solution.success;charge('design_nodes',len(grid));nodes=[equation(float(r),[float(b)],True) for r,b in zip(grid,solution.y[0])];save('design-nodes.json',{'nodes':nodes});rb=np.array([q['back_radius'] for q in nodes]);height=solution.y[0];slopes=np.array([q['height_derivative'] for q in nodes]);assert np.all(np.diff(rb)<0) and rb[-1]==0 and rb[0]==R,'Back radius is not ordered';assert np.all(height[1:]>0) and height[0]==0 and slopes[-1]==0 and all(q['mapping_derivative']>0 for q in nodes),'Height/center/branch failure'
 model=dict(model='Actual C1 cubic Hermite height; every normal differentiates this polynomial',radius_nodes=rb[::-1].tolist(),heights=height[::-1].tolist(),derivatives=slopes[::-1].tolist(),same_for_both_lengths=True,front_height=front.depth,front_power=8.,design_map='Canonical flat-front spline physical prior, not target RGB or a posttrace warp');charge('polynomial_bound_segments',len(rb)-1);actual=HermiteFootprintBack(base,model);model.update(maximum_height=actual.maximum_height,slope_bound=actual.slope_bound,certificate='Exact rational Bernstein controls of intended Hermite polynomial; not full floating-point interval arithmetic.');save('back-profile.json',model);np.savetxt(OUT/'back-profile.csv',np.c_[rb[::-1],height[::-1],slopes[::-1]],delimiter=',',header='back_radius,physical_height,actual_height_derivative',comments='')
 charge('profile_scalar_queries',2*len(rb));B=actual.profile(rb);m=actual.profile(rb,True);assert np.array_equal(B,height) and np.array_equal(m,slopes);normal=np.stack([-m,np.zeros_like(m),-np.ones_like(m)],axis=-1);normal/=np.linalg.norm(normal,axis=-1)[:,None];inside=np.array([q['inside_direction'] for q in nodes]);expected=np.array([q['direction'] for q in nodes]);charge('shared_Snell_points',len(rb));out,blocked,disc=refract(inside,-normal,n,1.);assert not blocked.any();direction_error=float(np.max(abs(out-expected)));source=rb+(-D+B)*out[:,0]/out[:,2];source_error=float(np.max(abs(source-np.array([q['target_source'] for q in nodes]))));assert direction_error<P['tolerances']['nodal_direction'] and source_error<P['tolerances']['nodal_source'];alpha=np.arctan(front.slope_bound);delta=alpha-np.arcsin(np.sin(alpha)/n);front_clearance=float(np.cos(delta)-front.slope_bound*np.sin(delta));back_clearance=float(np.cos(delta)-actual.slope_bound*np.sin(delta));reflection_clearance=float((1-3*front.slope_bound**2)/(1+front.slope_bound**2));assert min(front_clearance,back_clearance,reflection_clearance)>0
 save('nodal-validation.json',dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat(),nodes=len(rb),strict_interior_nodes=len(rb)-1,edge_limit_nodes=1,height_and_derivative_nodes_exact=True,maximum_direction_error=direction_error,maximum_source_error=source_error,minimum_radius_mapping_derivative=min(q['mapping_derivative'] for q in nodes),primary_front_global_clearance=front_clearance,primary_back_global_clearance=back_clearance,front_reflection_global_clearance=reflection_clearance,scope='Actual polynomial and shared Snell atdesignnodes; dense actual forwardpaths, outgoing escape and whole-sourceproof remain separate.'))
 last={f:sha(ROOT/f) for f in first};assert last==first;save('last-hashes.json',last);save('result.json',dict(status='ONE_COHERENT_BACK_CONSTRUCTED_NODAL_VALIDATION_ONLY',finished=datetime.datetime.now(datetime.timezone.utc).isoformat(),maximum_height=actual.maximum_height,slope_bound=actual.slope_bound,front_height=front.depth,power=8.,ODE_evaluations=solution.nfev,nodes=len(rb),minimum_radius_mapping_derivative=min(q['mapping_derivative'] for q in nodes),nodal_direction_error=direction_error,nodal_source_error=source_error,ledger=ledger,selected_model_changed=False,native_images=0,RGB_reads=0,fits_to_RGB=0,limits='Constructed actual geometry only. Sampled input-to-back monotonicity and global polynomial positivity are distinct. No wholeforward/source/fidelity or later-reflection acceptance.'));print(json.dumps({'height':actual.maximum_height,'slope':actual.slope_bound,'source_error':source_error,'ledger':ledger}),flush=True)
